package com.mobileai.assistant.domain.genui

import kotlinx.serialization.ExperimentalSerializationApi
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.JsonClassDiscriminator

/**
 * Root sealed interface for all user interaction events generated by GenUI components.
 */
@OptIn(ExperimentalSerializationApi::class)
@Serializable
@JsonClassDiscriminator("eventType")
sealed interface GenUiEvent {
    val componentId: String

    /**
     * User submitted a form.
     */
    @Serializable
    @SerialName("form_submit")
    data class FormSubmit(
        val formId: String,
        val actionId: String = "submit",
        val fieldValues: Map<String, String> = emptyMap(),
        override val componentId: String = formId
    ) : GenUiEvent

    /**
     * User clicked a button or action trigger.
     */
    @Serializable
    @SerialName("button_click")
    data class ButtonClick(
        val actionId: String,
        val payload: Map<String, String> = emptyMap(),
        override val componentId: String = ""
    ) : GenUiEvent

    /**
     * User changed a selection control (e.g. tabs, segmented buttons, dropdown).
     */
    @Serializable
    @SerialName("selection_change")
    data class SelectionChange(
        val selectedKey: String,
        val selectedLabel: String? = null,
        val payload: Map<String, String> = emptyMap(),
        override val componentId: String
    ) : GenUiEvent

    /**
     * User clicked a node within an interactive diagram.
     */
    @Serializable
    @SerialName("diagram_node_click")
    data class DiagramNodeClick(
        val diagramId: String,
        val nodeId: String,
        val nodeLabel: String? = null,
        override val componentId: String = diagramId
    ) : GenUiEvent
}

typealias ActionClick = GenUiEvent.ButtonClick

